    FrameworkElement StudyChart(JsonArray daily)
    {
        var g=new Grid{Height=132,Margin=new Thickness(0,10,0,0)};for(int i=0;i<7;i++)g.ColumnDefinitions.Add(new ColumnDefinition());var days=Enumerable.Range(0,7).Select(i=>DateTime.Today.AddDays(i-6)).ToArray();var vals=days.Select(d=>daily.Where(x=>DateTime.TryParse(S(x,"Date"),out var dt)&&dt.Date==d.Date).Sum(x=>N(x,"Duration (min)"))/60).ToArray();double max=Math.Max(1,vals.Max());for(int i=0;i<7;i++){var stack=new StackPanel{VerticalAlignment=VerticalAlignment.Bottom,HorizontalAlignment=HorizontalAlignment.Center};var h=new Grid{Height=92,VerticalAlignment=VerticalAlignment.Bottom,Width=28};h.Children.Add(new Border{Background=new SolidColorBrush(Color.FromRgb(41,48,65)),CornerRadius=new CornerRadius(5)});var fill=new Border{Background=Cyan,CornerRadius=new CornerRadius(5),Height=Math.Max(vals[i]>0?5:0,86*vals[i]/max),VerticalAlignment=VerticalAlignment.Bottom};h.Children.Add(fill);stack.Children.Add(h);stack.Children.Add(new TextBlock{Text=days[i].ToString("ddd"),Foreground=(Brush)FindResource("TextMuted"),FontSize=10,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,5,0,0)});g.Children.Add(stack);Grid.SetColumn(stack,i);}return g;
    }
