Render();};done.Click+=(_,_)=>win.Close();win.ShowDialog();}
    void Login(){var p=new StackPanel{Margin=new Thickness(14)};var email=new TextBox{Width=330,ToolTip="Email address"};var password=new PasswordBox{Width=330,Padding=new Thickness(10,7,10,7),Background=new SolidColorBrush(Color.FromRgb(14,17,25)),Foreground=(Brush)FindResource("TextMain"),BorderBrush=new SolidColorBrush(Color.FromRgb(48,57,74)),Margin=new Thickness(0,4,0,10)};p.Children.Add(new TextBlock{Text="Same account as your GrowJEE website",Foreground=(Brush)FindResource("TextMuted"),Margin=new Thickness(0,0,0,8)});p.Children.Add(email);p.Children.Add(password);var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var cancel=new Button{Content="Cancel"};var create=new Button{Content="Create account"};var login=new Button{Content="Sign in",Background=Cyan,Foreground=(Brush)FindResource("Ink")};buttons.Children.Add(cancel);buttons.Children.Add(create);buttons.Children.Add(login);p.Children.Add(buttons);var win=Popup("GrowJEE account",p,430,230);cancel.Click+=(_,_)=>win.Close();create.Click+=async(_,_)=>await Authenticate(email.Text,password.Password,true,win);login.Click+=async(_,_)=>await Authenticate(email.Text,password.Password,false,win);win.ShowDialog();}
    async Task Authenticate(string email,string password,bool create,Window dialog){if(string.IsNullOrWhiteSpace(email)||password.Length<6){MessageBox.Show(dialog,"Enter an email and password of at least six characters.");return;}try{var body=new JsonObject{["email"]=email.Trim(),["password"]=password};Session=await ApiRequest(create?"/auth/v1/signup":"/auth/v1/token?grant_type=password","POST",body) as JsonObject;if(Session is null||Session["access_token"] is null){MessageBox.Show(dialog,"Confirm your email, then sign in.");return;}Session["expires_at"]=DateTimeOffset.UtcNow.ToUnixTimeSeconds()+((long?)Session["expires_in"]??3600);SaveSession();dialog.Close();Render();await LoadCloud();}catch(Exception ex){MessageBox.Show(dialog,"Sign-in failed: "+ex.Message);}}
    Window Popup(string title,UIElement child,double width,double height){var w=new Window{Title=title,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Width=width,Height=height,ResizeMode=ResizeMode.NoResize,Background=(Brush)FindResource("Ink"),Foreground=(Brush)FindResource("TextMain"),Content=child};return w;}
    JsonObject Snapshot(){var daily=Records("daily");var questions=Records("questions");var mocks=Records("mocks");var master=Arr(Data["master"]);double mins=daily.Sum(x=>N(x,"Duration (min)")),attempt=questions.Sum(x=>N(x,"Attempted")),correct=questions.Sum(x=>N(x,"Correct"));var weak=new JsonArray();foreach(var c in master.Where(x=>S(x,"mockMarks")!=""&&Stars(N(x,"mockMarks"))<=2).OrderBy(x=>N(x,"mockMarks")))weak.Add(new JsonObject{["subject"]=S(c,"subject"),["chapter"]=S(c,"chapter"),["score"]=N(c,"mockMarks"),["stars"]=Stars(N(c,"mockMarks"))});var recent=new JsonArray();foreach(var m in mocks.OrderByDescending(x=>S(x,"Date")).Take(8))recent.Add(new JsonObject{["date"]=S(m,"Date"),["name"]=S(m,"Test name"),["exam"]=S(m,"Exam"),["score"]=S(m,"Total score"),["max"]=S(m,"Total max")});var progress=new JsonArray();foreach(var subj in Subjects){var all=master.Where(x=>S(x,"subject")==subj).ToList();progress.Add(new JsonObject{["subject"]=subj,["complete"]=all.Count(x=>S(x,"status")=="Completed"),["total"]=all.Count});}return new JsonObject{["studyMinutes"]=mins,["questionsAttempted"]=attempt,["questionsCorrect"]=correct,["accuracy"]=attempt==0?null:Math.Round(correct/attempt*100),["chaptersComplete"]=master.Count(x=>S(x,"status")=="Completed"),["chaptersTotal"]=master.Count,["subjectProgress"]=progress,["priorityChapters"]=weak,["mockTests"]=recent,["generatedAt"]=DateTime.UtcNow.ToString("o")};}
    async Task LoadCloud(){if(Session is null)return;Syncing=true;Render();try{var token=await AccessToken();var id=S(Obj(Session["user"]),"id");var rows=await ApiRequest("/rest/v1/jee_user_data?select=payload&user_id=eq."+Uri.EscapeDataString(id),"GET",null,token) as JsonArray;if(rows?.Count>0&&rows[0]?["payload"] is JsonObject payload)Data=(JsonObject)payload.DeepClone();else await PushData(token);PersistLocal();Syncing=false;Render();}catch(Exception ex){Syncing=false;Render();MessageBox.Show(this,"Cloud sync paused: "+ex.Message);}}
    async Task SyncCloud(){if(Session is null)return;Syncing=true;Render();try{await PushData(await AccessToken());await SyncShares();Syncing=false;Render();}catch(Exception ex){Syncing=false;Render();MessageBox.Show(this,"Saved on this PC. Cloud sync paused: "+ex.Message);}}
    async Task PushData(string token){var body=new JsonObject{["user_id"]=S(Obj(Session?["user"]),"id"),["payload"]=Data.DeepClone(),["updated_at"]=DateTime.UtcNow.ToString("o")};await ApiRequest("/rest/v1/jee_user_data?on_conflict=user_id","POST",body,token,"resolution=merge-duplicates,return=minimal");}
    async Task SyncShares(){var query="/rest/v1/jee_shares?student_id=eq."+Uri.EscapeDataString(S(Obj(Session?["user"]),"id"));await ApiRequest(query,"PATCH",new JsonObject{["progress_snapshot"]=Snapshot(),["snapshot_updated_at"]=DateTime.UtcNow.ToString("o")},await AccessToken(),"return=minimal");}
    async Task<JsonNode?> ApiRequest(string path,string method,JsonObject? body=null,string? token=null,string? prefer=null){using var req=new HttpRequestMessage(new HttpMethod(method),Api+path);req.Headers.Add("apikey",PublishableKey);if(token is not null)req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(prefer is not null)req.Headers.TryAddWithoutValidation("Prefer",prefer);if(body is not null)req.Content=new StringContent(body.ToJsonString(),Encoding.UTF8,"application/json");using var response=await Http.SendAsync(req);var raw=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode){try{var err=JsonNode.Parse(raw);throw new Exception(err?["message"]?.ToString()??err?["msg"]?.ToString()??err?["error_description"]?.ToString()??$"Request failed ({(int)response.StatusCode})");}catch(JsonException){throw new Exception($"Request failed ({(int)response.StatusCode})");}}return string.IsNullOrWhiteSpace(raw)?null:JsonNode.Parse(raw);}
    async Task<string> AccessToken(){if(Session is null)throw new Exception("Sign in again.");long exp=(long?)Session["expires_at"]??0;if(exp>DateTimeOffset.UtcNow.ToUnixTimeSeconds()+60)return S(Session,"access_token");var fresh=await ApiRequest("/auth/v1/token?grant_type=refresh_token","POST",new JsonObject{["refresh_token"]=S(Session,"refresh_token")}) as JsonObject??throw new Exception("Session expired.");Session=fresh;Session["expires_at"]=DateTimeOffset.UtcNow.ToUnixTimeSeconds()+((long?)fresh["expires_in"]??3600);SaveSession();return S(Session,"access_token");}
    void PersistLocal(){Directory.CreateDirectory(DataFolder);File.WriteAllText(DataPath,Data.ToJsonString(new JsonSerializerOptions{WriteIndented=true}));}
    JsonObject LoadLocal(){try{if(File.Exists(DataPath))return JsonNode.Parse(File.ReadAllText(DataPath))!.AsObject();}catch{}return FreshData();}
    JsonObject FreshData(){var master=new JsonArray();try{var chapters=JsonNode.Parse(File.ReadAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"chapters.json")))!.AsArray();for(int i=0;i<chapters.Count;i++){var c=chapters[i]!;master.Add(new JsonObject{["id"]="c"+i,["subject"]=S(c,"subject"),["chapter"]=S(c,"chapter"),["source"]=S(c,"source"),["status"]="Not Started",["confidence"]="",["mockMarks"]="",["mockDate"]="",["notes"]=""});}}catch{}return new JsonObject{["master"]=master,["records"]=new JsonObject{["daily"]=new JsonArray(),["questions"]=new JsonArray(),["mocks"]=new JsonArray(),["mistakes"]=new JsonArray(),["revisions"]=new JsonArray(),["targets"]=new JsonArray(),["chapterMarks"]=new JsonArray()}};}
    void MockMenu(JsonObject mock){var title=S(mock,"Test name","Mock test");var opts=new List<string>{"Edit mock","Linked mistakes","Attach question paper PDF","Attach answer sheet PDF"};if(mock["questionPdf"] is not null)opts.Add("Open question paper");if(mock["answerPdf"] is not null)opts.Add("Open answer sheet");var menu=new ContextMenu();foreach(var option in opts){var item=new MenuItem{Header=option};item.Click+=async(_,_)=>{if(option=="Edit mock")Edit("Mock Test Analytics",mock);else if(option=="Linked mistakes")ShowLinked(mock);else if(option.StartsWith("Attach"))await AttachPdf(mock,option.Contains("question")?"question":"answer");else await OpenPdf(mock,option.Contains("question")?"question":"answer");};menu.Items.Add(item);}var p=new StackPanel{Margin=new Thickness(10)};p.Children.Add(new TextBlock{Text=$"{S(mock,"Exam")} · {S(mock,"Date")} · {S(mock,"Total score","—")} / {S(mock,"Total max","—")}",Foreground=(Brush)FindResource("TextMuted"),Margin=new Thickness(0,0,0,12)});var choose=ActionButton("Choose action…",()=>menu.IsOpen=true,true);choose.ContextMenu=menu;p.Children.Add(choose);p.Children.Add(new TextBlock{Text=$"Question paper: {S(Obj(mock["questionPdf"]),"name","none attached")}\nAnswer sheet: {S(Obj(mock["answerPdf"]),"name","none attached")}\n\n{Linked(S(mock,"id"))} linked mistakes",TextWrapping=TextWrapping.Wrap});var win=Popup(title,p,430,250);win.ShowDialog();}
    void ShowLinked(JsonObject mock){var errors=Records("mistakes").Where(x=>S(x,"Mock test")==S(mock,"id")).ToList();var p=new StackPanel{Margin=new Thickness(14)};if(errors.Count==0)p.Children.Add(new TextBlock{Text="No mistakes are linked to this mock yet.",Foreground=(Brush)FindResource("TextMuted")});foreach(var e in errors){var b=new Border{Background=(Brush)FindResource("Panel"),CornerRadius=new CornerRadius(10),Padding=new Thickness(11),Margin=new Thickness(0,0,0,7)};b.Child=new TextBlock{Text=$"{S(e,"Chapter","Unspecified chapter")} · {S(e,"Subject")} · {S(e,"Mistake type")}\n{S(e,"What went wrong")}",TextWrapping=TextWrapping.Wrap};p.Children.Add(b);}Popup("Mistakes linked to "+S(mock,"Test name","mock"),new ScrollViewer{Content=p},450,430).ShowDialog();}
    async Task AttachPdf(JsonObject mock,string kind){var picker=new OpenFileDialog{Title="Choose a PDF",Filter="PDF files (*.pdf)|*.pdf",CheckFileExists=true};if(picker.ShowDialog(this)!=true)return;var info=new FileInfo(picker.FileName);if(info.Length>10*1024*1024){MessageBox.Show(this,"PDFs must be 10 MB or smaller.");return;}if(Session is null&&kind=="answer"){MessageBox.Show(this,"Sign in to store an answer sheet in cloud storage.");return;}byte[] bytes=await File.ReadAllBytesAsync(picker.FileName);var prop=kind+"Pdf";var localDir=System.IO.Path.Combine(DataFolder,"papers");Directory.CreateDirectory(localDir);var localPath=System.IO.Path.Combine(localDir,S(mock,"id")+"-"+kind+".pdf");await File.WriteAllBytesAsync(localPath,bytes);JsonObject meta=new(){["name"]=info.Name,["size"]=info.Length};if(Session is not null){try{string path=S(Obj(Session["user"]),"id")+"/"+S(mock,"id")+"/"+kind+".pdf";var token=await AccessToken();using var request=new HttpRequestMessage(HttpMethod.Post,Api+"/storage/v1/object/jee-mock-pdfs/"+string.Join("/",path.Split('/').Select(Uri.EscapeDataString)));request.Headers.Add("apikey",PublishableKey);request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);request.Headers.TryAddWithoutValidation("x-upsert","true");request.Content=new ByteArrayContent(bytes);request.Content.Headers.ContentType=new MediaTypeHeaderValue("application/pdf");using var response=await Http.SendAsync(request);var raw=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode)throw new Exception(raw);meta["storage"]="supabase";meta["path"]=path;meta["localCache"]=localPath;}catch(Exception ex){if(kind!="question"){MessageBox.Show(this,"Cloud PDF upload failed: "+ex.Message);return;}meta["storage"]="local";meta["key"]=localPath;MessageBox.Show(this,"Cloud upload failed. The question paper is saved on this PC only.\n"+ex.Message);}}else{meta["storage"]="local";meta["key"]=localPath;}mock[prop]=meta;PersistLocal();await SyncCloud();MockMenu(mock);}
    async Task OpenPdf(JsonObject mock,string kind){var meta=Obj(mock[kind+"Pdf"]);if(mock[kind+"Pdf"] is null){MessageBox.Show(this,"No PDF attached.");return;}try{string path=S(meta,"key",S(meta,"localCache"));if(S(meta,"storage")=="supabase"){var token=await AccessToken();var url=Api+"/storage/v1/object/authenticated/jee-mock-pdfs/"+string.Join("/",S(meta,"path").Split('/').Select(Uri.EscapeDataString));using var req=new HttpRequestMessage(HttpMethod.Get,url);req.Headers.Add("apikey",PublishableKey);req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);using var res=await Http.SendAsync(req);res.EnsureSuccessStatusCode();path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid()+".pdf");await File.WriteAllBytesAsync(path,await res.Content.ReadAsByteArrayAsync());}if(!File.Exists(path))throw new Exception("This PC does not have a copy of that local PDF.");Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(this,"Could not open PDF: "+ex.Message);}}
    int Linked(string id)=>Records("mistakes").Count(x=>S(x,"Mock test")==id);
    string MockName(string id)=>Records("mocks").FirstOrDefault(x=>S(x,"id")==id) is JsonNode m?S(m,"Test name","Mock test"):string.IsNullOrEmpty(id)?"No mock linked":"Saved mock";
    void Delete(string key,JsonObject item){if(MessageBox.Show(this,"Delete this entry?","GrowJEE",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;var a=key=="master"?Arr(Data["master"]):Records(key);for(int i=a.Count-1;i>=0;i--)if(S(a[i],"id")==S(item,"id"))a.RemoveAt(i);PersistLocal();Render();_ = SyncCloud();}
    void Export_Click(object sender,RoutedEventArgs e){var dlg=new SaveFileDialog{FileName="growjee-backup.json",Filter="JSON backup (*.json)|*.json"};if(dlg.ShowDialog(this)==true)File.WriteAllText(dlg.FileName,Data.ToJsonString(new JsonSerializerOptions{WriteIndented=true}));}
    void Import_Click(object sender,RoutedEventArgs e){var dlg=new OpenFileDialog{Filter="JSON backup (*.json)|*.json"};if(dlg.ShowDialog(this)!=true)return;try{Data=JsonNode.Parse(File.ReadAllText(dlg.FileName))!.AsObject();PersistLocal();Render();_ = SyncCloud();}catch(Exception ex){MessageBox.Show(this,"Could not import backup: "+ex.Message);}}
    void SaveSession(){if(Session is null)return;byte[] clear=Encoding.UTF8.GetBytes(Session.ToJsonString());byte[] encrypted=ProtectedData.Protect(clear,null,DataProtectionScope.CurrentUser);File.WriteAllBytes(SessionPath,encrypted);}
    JsonObject? ReadSession(){try{if(!File.Exists(SessionPath))return null;var clear=ProtectedData.Unprotect(File.ReadAllBytes(SessionPath),null,DataProtectionScope.CurrentUser);return JsonNode.Parse(clear) as JsonObject;}catch{return null;}}
}
